    tip2: 'PDF ରୁ କପି କରିଥିବା ଲେଖାର ଧାଡ଼ି ଭାଙ୍ଗିଯାଇଛି? ସଫା ଟ୍ୟାବରେ “PDF ର ଭଙ୍ଗା ଧାଡ଼ି ଯୋଡ଼ନ୍ତୁ” ଓ ତା’ପରେ “ଅଧିକା ସ୍ପେସ୍ ହଟାନ୍ତୁ” ଦବାନ୍ତୁ।',
    tip3: 'ଅଫିସ୍ ତାଲିକା: ନାମ ସ୍ତମ୍ଭ ପେଷ୍ଟ କରନ୍ତୁ, ତା’ପରେ “ଦୋହରା ଧାଡ଼ି ହଟାନ୍ତୁ” ଓ “ଧାଡ଼ି ସଜାନ୍ତୁ”। “ବାହାର କରନ୍ତୁ” ଲମ୍ବା WhatsApp ଚାଟ୍ ରୁ ପ୍ରତି ମୋବାଇଲ୍ ନମ୍ବର +91 98xxxxxxxx ଭାବେ ବାହାର କରେ।',
    tip4: 'ଶିକ୍ଷକ: ରୋଲ୍ ତାଲିକା ପାଇଁ ଧାଡ଼ିରେ ନମ୍ବର ଦିଅନ୍ତୁ, ବା ନାମଗୁଡ଼ିକୁ “, ” ଦେଇ ଯୋଡ଼ି ଗୋଟିଏ WhatsApp ବାର୍ତ୍ତା ପଠାନ୍ତୁ। ଛାତ୍ରଛାତ୍ରୀ: ରଚନାର ଦୁଇଟି ଖସଡ଼ାରେ କଣ ବଦଳିଲା ତାହା “ଦୁଇଟି ଲେଖା ତୁଳନା କରନ୍ତୁ” ରେ ଦେଖନ୍ତୁ।',
    tip5: '“କେବଳ ପୂରା ଶବ୍ଦ” ସହ ଖୋଜି-ବଦଳାଇଲେ “ରାମ” ବଦଳେ କିନ୍ତୁ “ରାମୁ” କୁ ଛୁଏଁ ନାହିଁ। ପ୍ୟାଟର୍ନ ଖୋଜା (regex) ତାରିଖ ପରି ଜିନିଷରେ ସାହାଯ୍ୟ କରେ।',
    tip6: 'ଆପଣଙ୍କ ଲେଖା କେବଳ ଏହି ଡିଭାଇସର ଏହି ବ୍ରାଉଜରରେ ସେଭ୍ ହୁଏ। ସବୁ ଲିଭାଇବାକୁ “ରିସେଟ୍” ଦବାନ୍ତୁ।'
