    app_title: 'టెక్స్ట్ టూల్స్: శుభ్రం & పోలిక',
    intro: 'ఏ టెక్స్ట్‌నైనా ఒకే చోట శుభ్రం చేసి మార్చండి: కేస్ మార్చండి, అదనపు ఖాళీలు, మళ్లీ వచ్చిన లైన్లు తీసేయండి, జాబితాను క్రమంలో పెట్టండి, వెతికి మార్చండి, ఈ-మెయిల్, మొబైల్ నంబర్లు బయటికి తీయండి, రెండు టెక్స్ట్‌లను పోల్చండి. తెలుగు, హిందీ, అన్ని భారతీయ భాషల్లో పనిచేస్తుంది.',
