    tip1: 'పెద్ద పెట్టెలో టెక్స్ట్ పేస్ట్ చేసి, ఒక ట్యాబ్ తెరిచి టూల్ నొక్కండి. ప్రతి మార్పును “వెనక్కి” (Ctrl+Z)తో ఒక్కో అడుగు వెనక్కి తీసుకోవచ్చు.',
    tip2: 'PDF నుండి కాపీ చేసిన టెక్స్ట్ లైన్లు విరిగిపోయాయా? శుభ్రం విభాగంలో “PDF విరిగిన లైన్లు కలుపు”, తర్వాత “అదనపు ఖాళీలు తీసేయి” నొక్కండి.',
