    tip4: 'ఉపాధ్యాయులు: హాజరు జాబితా కోసం లైన్లకు నంబర్లు వేయండి, లేదా పేర్లను “, ” తో కలిపి ఒక WhatsApp సందేశం పంపండి. విద్యార్థులు: వ్యాసం రెండు చిత్తుప్రతుల్లో ఏం మారిందో “రెండు టెక్స్ట్‌లు పోల్చండి”లో చూడండి.',
    tip5: '“పూర్తి పదాలు మాత్రమే”తో వెతికి మారిస్తే “రామ్” మారుతుంది, “రాము” మారదు. నమూనా వెతుకులాట (regex) తేదీల లాంటి వాటికి సహాయపడుతుంది.',
    tip6: 'మీ టెక్స్ట్ ఈ పరికరంలోని ఈ బ్రౌజర్‌లో మాత్రమే సేవ్ అవుతుంది. అన్నీ తుడిచేయడానికి “రీసెట్” నొక్కండి.'
