    intro: 'ಯಾವುದೇ ಪಠ್ಯವನ್ನು ಒಂದೇ ಕಡೆ ಸ್ವಚ್ಛಗೊಳಿಸಿ ಬದಲಿಸಿ: ಕೇಸ್ ಬದಲಿಸಿ, ಹೆಚ್ಚುವರಿ ಸ್ಪೇಸ್ ಮತ್ತು ಮತ್ತೆ ಬಂದ ಸಾಲುಗಳನ್ನು ತೆಗೆಯಿರಿ, ಪಟ್ಟಿಯನ್ನು ಕ್ರಮದಲ್ಲಿ ಜೋಡಿಸಿ, ಹುಡುಕಿ ಬದಲಿಸಿ, ಇ-ಮೇಲ್ ಮತ್ತು ಮೊಬೈಲ್ ಸಂಖ್ಯೆಗಳನ್ನು ತೆಗೆಯಿರಿ, ಎರಡು ಪಠ್ಯಗಳನ್ನು ಹೋಲಿಸಿ. ಕನ್ನಡ, ಹಿಂದಿ ಮತ್ತು ಎಲ್ಲ ಭಾರತೀಯ ಭಾಷೆಗಳಲ್ಲಿ ಕೆಲಸ ಮಾಡುತ್ತದೆ.',
