    cmp_same_ign: 'ಯಾವ ವ್ಯತ್ಯಾಸವೂ ಇಲ್ಲ (ದೊಡ್ಡ-ಸಣ್ಣ ಅಕ್ಷರ ಮತ್ತು ಹೆಚ್ಚುವರಿ ಸ್ಪೇಸ್ ನೋಡಿಲ್ಲ).',
