    msg_failed: 'ಏನೋ ತಪ್ಪಾಯಿತು. ನಿಮ್ಮ ಪಠ್ಯ ಬದಲಾಗಿಲ್ಲ.',
    msg_ex_empty: 'ಪಟ್ಟಿ ಖಾಲಿ ಇದೆ.',
    msg_ex_used: 'ಪಟ್ಟಿ ({n} ಅಂಶಗಳು) ಈಗ ಪಠ್ಯ ಪೆಟ್ಟಿಗೆಯಲ್ಲಿದೆ. ಹಿಂದೆ ಹೋಗಲು “ಹಿಂದಿನಂತೆ” ಒತ್ತಿ.',
    help_h: 'ಬಳಸುವುದು ಹೇಗೆ / ಕೆಲಸದ ಐಡಿಯಾಗಳು',
    tip1: 'ದೊಡ್ಡ ಪೆಟ್ಟಿಗೆಯಲ್ಲಿ ಪಠ್ಯ ಅಂಟಿಸಿ, ಒಂದು ಟ್ಯಾಬ್ ತೆರೆದು ಉಪಕರಣ ಒತ್ತಿ. ಪ್ರತಿ ಬದಲಾವಣೆಯನ್ನು “ಹಿಂದಿನಂತೆ” (Ctrl+Z) ಮೂಲಕ ಹೆಜ್ಜೆ ಹೆಜ್ಜೆಯಾಗಿ ಹಿಂಪಡೆಯಬಹುದು.',
    tip2: 'PDF ನಿಂದ ನಕಲಿಸಿದ ಪಠ್ಯದ ಸಾಲುಗಳು ಮುರಿದಿವೆಯೇ? ಸ್ವಚ್ಛ ವಿಭಾಗದಲ್ಲಿ “PDF ಮುರಿದ ಸಾಲುಗಳನ್ನು ಜೋಡಿಸಿ”, ನಂತರ “ಹೆಚ್ಚುವರಿ ಸ್ಪೇಸ್ ತೆಗೆಯಿರಿ” ಒತ್ತಿ.',
    tip3: 'ಕಚೇರಿ ಪಟ್ಟಿಗಳು: ಹೆಸರುಗಳ ಕಾಲಮ್ ಅಂಟಿಸಿ, ನಂತರ “ಮತ್ತೆ ಬಂದ ಸಾಲುಗಳನ್ನು ತೆಗೆಯಿರಿ” ಮತ್ತು “ಸಾಲುಗಳನ್ನು ಕ್ರಮದಲ್ಲಿ ಜೋಡಿಸಿ”. “ತೆಗೆಯಿರಿ” ಉದ್ದ WhatsApp ಚಾಟ್‌ನಿಂದ ಪ್ರತಿ ಮೊಬೈಲ್ ಸಂಖ್ಯೆಯನ್ನು +91 98xxxxxxxx ಎಂದು ತೆಗೆಯುತ್ತದೆ.',
    tip4: 'ಶಿಕ್ಷಕರು: ಹಾಜರಾತಿ ಪಟ್ಟಿಗೆ ಸಾಲುಗಳಿಗೆ ಸಂಖ್ಯೆ ಕೊಡಿ, ಅಥವಾ ಹೆಸರುಗಳನ್ನು “, ” ನಿಂದ ಜೋಡಿಸಿ ಒಂದು WhatsApp ಸಂದೇಶ ಕಳುಹಿಸಿ. ವಿದ್ಯಾರ್ಥಿಗಳು: ಪ್ರಬಂಧದ ಎರಡು ಕರಡುಗಳಲ್ಲಿ ಏನು ಬದಲಾಯಿತು ಎಂದು “ಎರಡು ಪಠ್ಯಗಳನ್ನು ಹೋಲಿಸಿ” ಯಲ್ಲಿ ನೋಡಿ.',
    tip5: '“ಪೂರ್ಣ ಪದಗಳು ಮಾತ್ರ” ಜೊತೆ ಹುಡುಕಿ ಬದಲಿಸಿದರೆ “ರಾಮ” ಬದಲಾಗುತ್ತದೆ, “ರಾಮು” ಅಲ್ಲ. ಮಾದರಿ ಹುಡುಕಾಟ (regex) ದಿನಾಂಕಗಳಂತಹವಕ್ಕೆ ನೆರವಾಗುತ್ತದೆ.',
    tip6: 'ನಿಮ್ಮ ಪಠ್ಯ ಈ ಸಾಧನದ ಈ ಬ್ರೌಸರ್‌ನಲ್ಲಿ ಮಾತ್ರ ಉಳಿಯುತ್ತದೆ. ಎಲ್ಲವನ್ನೂ ಅಳಿಸಲು “ಮರುಹೊಂದಿಸಿ” ಒತ್ತಿ.'
