    tip4: 'അധ്യാപകർ: ഹാജർ പട്ടികയ്ക്കായി വരികൾക്ക് നമ്പർ ഇടൂ, അല്ലെങ്കിൽ പേരുകൾ “, ” കൊണ്ട് ചേർത്ത് ഒരു WhatsApp സന്ദേശം അയയ്ക്കൂ. വിദ്യാർത്ഥികൾ: ഉപന്യാസത്തിന്റെ രണ്ട് കരടുകളിൽ എന്ത് മാറി എന്ന് “രണ്ട് ടെക്സ്റ്റുകൾ താരതമ്യം ചെയ്യുക”-ൽ കാണൂ.',
    tip5: '“മുഴുവൻ വാക്കുകൾ മാത്രം” ഉപയോഗിച്ച് തിരഞ്ഞ് മാറ്റിയാൽ “രാമൻ” മാറും, “രാമു” മാറില്ല. പാറ്റേൺ തിരയൽ (regex) തീയതികൾ പോലുള്ളവയ്ക്ക് സഹായിക്കും.',
    tip6: 'നിങ്ങളുടെ ടെക്സ്റ്റ് ഈ ഉപകരണത്തിലെ ഈ ബ്രൗസറിൽ മാത്രമാണ് സേവ് ചെയ്യുന്നത്. എല്ലാം മായ്ക്കാൻ “റീസെറ്റ്” അമർത്തൂ.'
